tool_schemas.schema/grep_repo:
{
  "name": "grep_repo",
  "description": "Search a committed snapshot of the repository (\"base\" default or\n\"pr\") for a literal string or regular expression. Use it to confirm a\nknown location or find literal text. Optionally restrict to files\nmatching file_glob (e.g. '*.py'). Returns matches as\n'file:line:content' (limited count).",
  "openai": {
    "type": "function",
    "function": {
      "name": "grep_repo",
      "description": "Search a committed snapshot of the repository (\"base\" default or\n\"pr\") for a literal string or regular expression. Use it to confirm a\nknown location or find literal text. Optionally restrict to files\nmatching file_glob (e.g. '*.py'). Returns matches as\n'file:line:content' (limited count).",
      "parameters": {
        "properties": {
          "pattern": {
            "type": "string"
          },
          "file_glob": {
            "default": "",
            "type": "string"
          },
          "snapshot": {
            "default": "base",
            "type": "string"
          }
        },
        "required": [
          "pattern"
        ],
        "type": "object"
      }
    }
  }
}

tool_schemas.schema/investigate_base_code:
{
  "name": "investigate_base_code",
  "description": "Explore the base snapshot (code before the PR) to discover what is\ninvolved: related definitions, callers and call paths. Query the\nCodeGraph index with a natural-language question or symbol and file\nnames; returns source fragments that can be partial or truncated,\nso use read_file for the exact lines you will cite.",
  "openai": {
    "type": "function",
    "function": {
      "name": "investigate_base_code",
      "description": "Explore the base snapshot (code before the PR) to discover what is\ninvolved: related definitions, callers and call paths. Query the\nCodeGraph index with a natural-language question or symbol and file\nnames; returns source fragments that can be partial or truncated,\nso use read_file for the exact lines you will cite.",
      "parameters": {
        "properties": {
          "query": {
            "type": "string"
          }
        },
        "required": [
          "query"
        ],
        "type": "object"
      }
    }
  }
}

