tool_schemas.schema/read_file:
{
  "name": "read_file",
  "description": "Read the exact lines of a file from a committed snapshot of the\nrepository: \"base\" (default) or \"pr\". Use it to see and quote\nprecise lines, including code that investigate_* located or only\npartly showed. Use start_line/end_line\n(1-based, inclusive) to read a specific range; pass 0 for both to\nread from the beginning. Returns numbered lines.",
  "openai": {
    "type": "function",
    "function": {
      "name": "read_file",
      "description": "Read the exact lines of a file from a committed snapshot of the\nrepository: \"base\" (default) or \"pr\". Use it to see and quote\nprecise lines, including code that investigate_* located or only\npartly showed. Use start_line/end_line\n(1-based, inclusive) to read a specific range; pass 0 for both to\nread from the beginning. Returns numbered lines.",
      "parameters": {
        "properties": {
          "path": {
            "type": "string"
          },
          "start_line": {
            "default": 0,
            "type": "integer"
          },
          "end_line": {
            "default": 0,
            "type": "integer"
          },
          "snapshot": {
            "default": "base",
            "type": "string"
          }
        },
        "required": [
          "path"
        ],
        "type": "object"
      }
    }
  }
}

